import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import RemoveRedEyeIcon from "@mui/icons-material/RemoveRedEye";
import { useEffect, useState } from "react";

function TableCareer({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  toggleView,
  status,
}) {
  const statusColors = {
    inactive: "#3A3541AD",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  const [activeData, setActiveData] = useState([]);
  const [inActiveData, setInActiveData] = useState([]);
  useEffect(() => {
    const activeRows = rows.filter((row) => row.status === "active");
    setActiveData(activeRows);
    const inActiveRows = rows.filter((row) => row.status === "inactive");
    setInActiveData(inActiveRows);
  }, [rows]);
  const displayedRows =
    status === "active"
      ? activeData
      : status === "inactive"
      ? inActiveData
      : rows;
  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={displayedRows}
      columns={[
        {
          field: "position",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Position",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.position}>
              {row.position}
            </Typography>
          ),
        },
        {
          field: "department",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Department",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.department}>
              {row.department}
            </Typography>
          ),
        },
        {
          field: "education",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Education",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.education}>
              {row.education}
            </Typography>
          ),
        },
        {
          field: "experience",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Experience",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.experience}>
              {row.experience}
            </Typography>
          ),
        },
        {
          field: "loaction",
          flex: 1,
          minWidth: 250,
          sortable: false,
          headerName: "Location",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.loaction}>
              {row.loaction}
            </Typography>
          ),
        },
        // {
        //   field: "about_one_thing_description",
        //   minWidth: 700,
        //   sortable: false,
        //   headerName: "About Onething",
        //   renderCell: ({ row }) => (
        //     <Typography
        //       noWrap
        //       variant="body2"
        //       title={row.about_one_thing_description}
        //     >
        //       {row.about_one_thing_description}
        //     </Typography>
        //   ),
        // },
        // {
        //   field: "key_responsibilities_description",
        //   minWidth: 700,
        //   sortable: false,
        //   headerName: "Key Responsibilities",
        //   renderCell: ({ row }) => (
        //     <Typography
        //       noWrap
        //       variant="body2"
        //       title={row.key_responsibilities_description}
        //     >
        //       {row.key_responsibilities_description}
        //     </Typography>
        //   ),
        // },
        // {
        //   field: "job_requirements_description",
        //   minWidth: 700,
        //   sortable: false,
        //   headerName: "Job requirements",
        //   renderCell: ({ row }) => (
        //     <Typography
        //       noWrap
        //       variant="body2"
        //       title={row.job_requirements_description}
        //     >
        //       {row.job_requirements_description}
        //     </Typography>
        //   ),
        // },
        {
          field: "status",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Status",
          renderCell: ({ row }) => <CustomChip label={row.status} />,
        },
        {
          field: "Actions",
          flex: 0,
          minWidth: 170,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleEdit(e, "edit", row)}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => toggleDelete(e, row)}
              >
                <DeleteIcon />
              </IconButton>
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleView(e, row)}
              >
                <RemoveRedEyeIcon />
              </IconButton>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
}

export default TableCareer;
