import { useEffect, useState, useRef, useCallback } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import TableCareer from "src/views/tables/TableCareer";
import DialogFormCareer from "src/views/dialog/DialogFormCareer";
import DialogViewCareerInfo from "src/views/dialog/DialogViewCareerInfo";

const CareerPage = () => {
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState(" ");
  const [careerData, setCareerData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );

  // Testimonials
  const [careerFormDialogOpen, setCareerFormDialogOpen] = useState(false);
  const [careerFormDialogMode, setCareerFormDialogMode] = useState("add");
  const [careerToEdit, setCareerToEdit] = useState(null);
  const [contactViewFormDialogOpen, setContactViewFormDialogOpen] =
    useState(false);

  const toggleCareerFormDialog = (e, mode = "add", careerToEdit = null) => {
    setCareerFormDialogOpen((prev) => !prev);
    setCareerFormDialogMode(mode);
    setCareerToEdit(careerToEdit);
  };

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [careerToDelete, setCareerToDelete] = useState(null);

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setCareerToDelete(dataToDelete);
  };

  const toggleContactViewFormDialog = (e, careerToEdit = null) => {
    setContactViewFormDialogOpen((prev) => !prev);
    setCareerToEdit(careerToEdit);
  };
  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.Career.list, { params })
      .then((response) => {
        setCareerData(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  //SEARCH
  useEffect(() => {
    if (!search) {
      // If search input is empty, show all data
      setCareerData(careerData);
    } else {
      // Filter the contactData based on the search value
      const filtered = careerData.filter(
        (item) =>
          item.position.toLowerCase().includes(search.toLowerCase()) ||
          item.education.toLowerCase().includes(search.toLowerCase()) ||
          item.department.toLowerCase().includes(search.toLowerCase())
      );
      setCareerData(filtered); // Set the filtered data
    }
  }, [search, careerData]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.Career.delete(careerToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, careerToDelete, pageSize, search]
  );

  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Career" />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleCareerFormDialog}>
              Add Career
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              {/* <Box></Box> */}
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "all" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"all"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box>
            <Box sx={{ p: 5 }}>
              <TableCareer
                status={status}
                search={search}
                loading={loading}
                rows={careerData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleCareerFormDialog}
                toggleView={toggleContactViewFormDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>

      <DialogFormCareer
        mode={careerFormDialogMode}
        open={careerFormDialogOpen}
        toggle={toggleCareerFormDialog}
        dataToEdit={careerToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Career"
        subtitle="Are you sure you want to delete this Career?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
      <DialogViewCareerInfo
        open={contactViewFormDialogOpen}
        toggle={toggleContactViewFormDialog}
        dataToEdit={careerToEdit}
      />
    </>
  );
};

export default CareerPage;
