import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  Radio,
  RadioGroup,
  TextField,
  Typography,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";

import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";

const validationSchema = yup.object().shape({
  position: yup.string().trim().max(50).required("Please add a Position."),
  department: yup.string().trim().required("Please add a Department."),
  experience: yup.string().trim().required("Please add Experience."),
  loaction: yup.string().trim().required("Please add Location."),
  education: yup.string().trim().required("Please enter Education."),
  about_one_thing_description: yup
    .string()
    .trim()
    .required("Please add a About Onething."),
  key_responsibilities_description: yup
    .string()
    .trim()
    .required("Please add a Key Responsibilities."),
  // job_requirements_points: yup
  //   .string()
  //   // .trim()
  //   .required("Please add a job description."),
});

const DialogFormCareer = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const [keyResponsibilities, setKeyResponsibilities] = useState([]);
  const [keyResponsibilitiesInput, setKeyResponsibilitiesInput] = useState("");
  const [jobRequirements, setJobRequirements] = useState([]);
  const [jobRequirementsInput, setJobRequirementsInput] = useState("");
  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      position: "",
      department: "",
      experience: "",
      loaction: "",
      education: "",
      about_one_thing_description: "",
      key_responsibilities_description: "",
      responsibilities: [], //key responsibilities points
      jobRequirements: [], //job description points
      status: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });
  const handleAddKeyResponsibilities = () => {
    if (keyResponsibilitiesInput.trim()) {
      setKeyResponsibilities([
        ...keyResponsibilities,
        { responsibilities_text: keyResponsibilitiesInput.trim() },
      ]);
      setKeyResponsibilitiesInput("");
    }
  };
  const handleAddJobRequirements = () => {
    if (jobRequirementsInput.trim()) {
      setJobRequirements([
        ...jobRequirements,
        { text: jobRequirementsInput.trim() },
      ]);
      setJobRequirementsInput("");
    }
  };

  const handleDeleteResponsibilities = (keyResponsibilityToDelete) => {
    setKeyResponsibilities((prevResponsibilities) =>
      prevResponsibilities.filter(
        (responsibility, index) => index !== keyResponsibilityToDelete
      )
    );
  };
  const handleDeleteEditResponsibilities = (responsibilityToDelete) => {
    axiosInstance
      .delete(
        ApiEndPoints.Career.deleteResponsibilities(responsibilityToDelete.id)
      )
      .then((response) => response.data)
      .then((response) => {
        setKeyResponsibilities((prevResponsibilities) =>
          prevResponsibilities.filter(
            (responsibility) => responsibility.id !== responsibilityToDelete.id
          )
        );
        toastSuccess(response.data.message);
      })
      .catch((error) => {
        toastError(error);
      });
  };

  const handleDeleteJobRequirements = (jobRequirementToDelete) => {
    setJobRequirements((prevResponsibilities) =>
      prevResponsibilities.filter(
        (requirements, index) => index !== jobRequirementToDelete
      )
    );
  };
  const handleDeleteEditJobRequirements = (requirementsToDelete) => {
    axiosInstance
      .delete(
        ApiEndPoints.Career.deleteJobRequirements(requirementsToDelete.id)
      )
      .then((response) => response.data)
      .then((response) => {
        setJobRequirements((prevRequirements) =>
          prevRequirements.filter(
            (requirement) => requirement.id !== requirementsToDelete.id
          )
        );
        toastSuccess(response.message);
      })
      .catch((error) => {
        toastError(error);
      });
  };
  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add Career" : "Edit Career");

      if (mode === "edit") {
        setJobRequirements(dataToEdit?.jobRequirements);
        setKeyResponsibilities(dataToEdit?.responsibilities);
      }

      reset({
        position: dataToEdit?.position || "",
        department: dataToEdit?.department || "",
        experience: dataToEdit?.experience || "",
        loaction: dataToEdit?.loaction || "",
        education: dataToEdit?.education || "",
        status: dataToEdit?.status || "",
        about_one_thing_description:
          dataToEdit?.about_one_thing_description || "",
        key_responsibilities_description:
          dataToEdit?.key_responsibilities_description || "",
        responsibilities: dataToEdit?.responsibilities || [],
        jobRequirements: dataToEdit?.jobRequirements || [],
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    let payload = {
      position: data.position,
      department: data.department,
      experience: data.experience,
      loaction: data.loaction,
      education: data.education,
      about_one_thing_description: data.about_one_thing_description,
      key_responsibilities_description: data.key_responsibilities_description,
      responsibilities: keyResponsibilities, //key responsibilities points
      jobRequirements: jobRequirements, //job description points
      ...(mode === "edit" && { status: data.status }),
    };

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.Career.edit(dataToEdit.id),
        payload,
        {}
      );
    } else {
      apiInstance = axiosInstance.post(ApiEndPoints.Career.create, payload, {});
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
        setKeyResponsibilities([]);
        setJobRequirements([]);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="hub-address-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="position"
                    error={Boolean(errors.position)}
                  >
                    Position
                  </FormLabel>
                  <Controller
                    name="position"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Position"
                        onChange={onChange}
                        id="position"
                        value={value}
                        error={Boolean(errors.position)}
                      />
                    )}
                  />
                  {errors.position && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.position.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="department"
                    error={Boolean(errors.department)}
                  >
                    Department
                  </FormLabel>
                  <Controller
                    name="department"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Department"
                        onChange={onChange}
                        id="department"
                        value={value}
                        error={Boolean(errors.department)}
                      />
                    )}
                  />
                  {errors.department && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.department.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="education"
                    error={Boolean(errors.education)}
                  >
                    Education
                  </FormLabel>
                  <Controller
                    name="education"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Education"
                        onChange={onChange}
                        id="education"
                        value={value}
                        error={Boolean(errors.education)}
                      />
                    )}
                  />
                  {errors.education && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.education.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="experience"
                    error={Boolean(errors.experience)}
                  >
                    Experience
                  </FormLabel>
                  <Controller
                    name="experience"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Experience"
                        onChange={onChange}
                        id="experience"
                        value={value}
                        error={Boolean(errors.question)}
                      />
                    )}
                  />
                  {errors.experience && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.experience.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="loaction"
                    error={Boolean(errors.loaction)}
                  >
                    Location
                  </FormLabel>
                  <Controller
                    name="loaction"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Loaction"
                        onChange={onChange}
                        id="loaction"
                        value={value}
                        error={Boolean(errors.loaction)}
                      />
                    )}
                  />
                  {errors.loaction && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.loaction.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="about_one_thing_description"
                    error={Boolean(errors.about_one_thing_description)}
                  >
                    About Onething
                  </FormLabel>
                  <Controller
                    name="about_one_thing_description"
                    control={control}
                    render={({ field }) => (
                      <ReactQuill
                        theme="snow"
                        {...field}
                        modules={{
                          toolbar: [
                            [{ header: [1, 2, 3, 4, 5, 6, false] }],
                            ["bold", "italic", "underline", "strike"],
                            ["blockquote", "code-block"],
                            [{ list: "ordered" }, { list: "bullet" }],
                            [{ script: "sub" }, { script: "super" }],
                            [{ indent: "-1" }, { indent: "+1" }],
                            [{ direction: "rtl" }],
                            [{ size: ["small", false, "large", "huge"] }],
                            [{ color: [] }, { background: [] }],
                            [{ font: [] }],
                            ["link"],
                            ["clean"],
                          ],
                        }}
                        formats={[
                          "header",
                          "font",
                          "size",
                          "bold",
                          "italic",
                          "underline",
                          "strike",
                          "blockquote",
                          "list",
                          "bullet",
                          "indent",
                          "script",
                          "link",
                          "color",
                          "background",
                        ]}
                        onChange={(value) => {
                          setValue("about_one_thing_description", value, {
                            shouldValidate: true,
                          });
                          field.onChange(value);
                        }}
                      />
                    )}
                  />
                  {errors.about_one_thing_description && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.about_one_thing_description.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="key_responsibilities_description"
                    error={Boolean(errors.key_responsibilities_description)}
                  >
                    Key Responsibilities
                  </FormLabel>
                  <Controller
                    name="key_responsibilities_description"
                    control={control}
                    render={({ field }) => (
                      <ReactQuill
                        theme="snow"
                        {...field}
                        modules={{
                          toolbar: [
                            [{ header: [1, 2, 3, 4, 5, 6, false] }],
                            ["bold", "italic", "underline", "strike"],
                            ["blockquote", "code-block"],
                            [{ list: "ordered" }, { list: "bullet" }],
                            [{ script: "sub" }, { script: "super" }],
                            [{ indent: "-1" }, { indent: "+1" }],
                            [{ direction: "rtl" }],
                            [{ size: ["small", false, "large", "huge"] }],
                            [{ color: [] }, { background: [] }],
                            [{ font: [] }],
                            ["link"],
                            ["clean"],
                          ],
                        }}
                        formats={[
                          "header",
                          "font",
                          "size",
                          "bold",
                          "italic",
                          "underline",
                          "strike",
                          "blockquote",
                          "list",
                          "bullet",
                          "indent",
                          "script",
                          "link",
                          "color",
                          "background",
                        ]}
                        onChange={(value) => {
                          setValue("key_responsibilities_description", value, {
                            shouldValidate: true,
                          });
                          field.onChange(value);
                        }}
                      />
                    )}
                  />
                  {errors.key_responsibilities_description && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.key_responsibilities_description.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12} pb={3}>
                <FormControl fullWidth>
                  <FormLabel
                    htmlFor="key_responsibilities_points"
                    error={Boolean(errors.key_responsibilities_points)}
                  >
                    Key Responsibilities Points
                  </FormLabel>
                  <Controller
                    name="key_responsibilities_points"
                    control={control}
                    defaultValue=""
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        type="text"
                        variant="standard"
                        onChange={(e) => {
                          onChange(keyResponsibilities);
                          setKeyResponsibilitiesInput(e.target.value);
                        }}
                        id="key_responsibilities_points"
                        value={keyResponsibilitiesInput}
                        InputProps={{
                          endAdornment: (
                            <InputAdornment position="end">
                              <IconButton
                                disableRipple
                                onClick={handleAddKeyResponsibilities}
                              >
                                <Typography
                                  fontWeight={700}
                                  color={"#602de1c2"}
                                >
                                  Add
                                </Typography>
                              </IconButton>
                            </InputAdornment>
                          ),
                        }}
                      />
                    )}
                  />
                </FormControl>
              </Grid>
              {keyResponsibilities?.length > 0 && (
                <Grid item xs={12}>
                  <Box
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      gap: 1,
                      border: "1px solid #ccc",
                      my: 3,
                      py: 2,
                      px: 3,
                      borderRadius: "5px",
                      width: "100%",
                    }}
                  >
                    {keyResponsibilities?.map((responsibility, index) => (
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "end",
                          justifyContent: "space-between",
                          gap: 3,
                          flexGrow: 1,
                        }}
                        key={index}
                      >
                        <Typography sx={{ fontSize: "14px" }}>
                          {index + 1}. {responsibility.responsibilities_text}
                        </Typography>
                        <IconButton
                          onClick={() =>
                            mode === "edit"
                              ? handleDeleteEditResponsibilities(responsibility)
                              : handleDeleteResponsibilities(
                                  responsibility,
                                  index
                                )
                          }
                        >
                          <CloseIcon
                            sx={{ fontSize: "16px", color: "#602de1c2" }}
                          />
                        </IconButton>
                      </Box>
                    ))}
                  </Box>
                </Grid>
              )}
              <Grid item xs={12} pb={3}>
                <FormControl fullWidth>
                  <FormLabel
                    htmlFor="job_requirements_points"
                    error={Boolean(errors.job_requirements_points)}
                  >
                    Job Requirements Points
                  </FormLabel>
                  <Controller
                    name="job_requirements_points"
                    control={control}
                    defaultValue=""
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        type="text"
                        variant="standard"
                        onChange={(e) => {
                          onChange(jobRequirements); // Update with array of services
                          setJobRequirementsInput(e.target.value);
                        }}
                        id="job_requirements_points"
                        value={jobRequirementsInput}
                        InputProps={{
                          endAdornment: (
                            <InputAdornment position="end">
                              <IconButton
                                disableRipple
                                onClick={handleAddJobRequirements}
                              >
                                <Typography
                                  fontWeight={700}
                                  color={"#602de1c2"}
                                >
                                  Add
                                </Typography>
                              </IconButton>
                            </InputAdornment>
                          ),
                        }}
                      />
                    )}
                  />
                </FormControl>
              </Grid>
              {jobRequirements?.length > 0 && (
                <Grid item xs={12}>
                  <Box
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      gap: 1,
                      border: "1px solid #ccc",
                      my: 3,
                      py: 2,
                      px: 3,
                      borderRadius: "5px",
                      width: "100%",
                    }}
                  >
                    {jobRequirements?.map((requirements, index) => (
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "end",
                          justifyContent: "space-between",
                          gap: 3,
                          flexGrow: 1,
                        }}
                        key={index}
                      >
                        <Typography sx={{ fontSize: "14px" }}>
                          {index + 1}. {requirements.text}
                        </Typography>

                        <IconButton
                          onClick={() =>
                            mode === "edit"
                              ? handleDeleteEditJobRequirements(requirements)
                              : handleDeleteJobRequirements(index)
                          }
                        >
                          <CloseIcon
                            sx={{ fontSize: "16px", color: "#602de1c2" }}
                          />
                        </IconButton>
                      </Box>
                    ))}
                  </Box>
                </Grid>
              )}
              {mode === "edit" && (
                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <FormLabel
                      required
                      htmlFor="status"
                      error={Boolean(errors.status)}
                    >
                      Status
                    </FormLabel>
                    <Controller
                      name="status"
                      control={control}
                      render={({ field: { value, onChange } }) => (
                        <RadioGroup
                          row
                          name="status"
                          onChange={onChange}
                          value={value}
                        >
                          <FormControlLabel
                            value={"active"}
                            control={<Radio />}
                            label="Active"
                          />
                          <FormControlLabel
                            value={"inactive"}
                            control={<Radio />}
                            label="Inactive"
                          />
                        </RadioGroup>
                      )}
                    />
                    {errors.status && (
                      <FormHelperText sx={{ color: "error.main" }}>
                        {errors.status.message}
                      </FormHelperText>
                    )}
                  </FormControl>
                </Grid>
              )}
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="hub-address-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogFormCareer;
